import{_ as e,a}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as r}from"./chunks/ts-mic-privacy.DXgfNaDe.js";import{_ as d,o as h,c as n,ag as o}from"./chunks/framework.DTisvaUJ.js";const f=JSON.parse('{"title":"故障排除 — 没有声音或无法识别","description":"介绍Mutelink无朗读声音、麦克风不识别或无法向VRChat发送文字时的检查步骤。","frontmatter":{"title":"故障排除 — 没有声音或无法识别","description":"介绍Mutelink无朗读声音、麦克风不识别或无法向VRChat发送文字时的检查步骤。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"故障排除 — 没有声音或无法识别 | Mutelink"}],["meta",{"property":"og:description","content":"介绍Mutelink无朗读声音、麦克风不识别或无法向VRChat发送文字时的检查步骤。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"故障排除 — 没有声音或无法识别 | Mutelink"}],["meta",{"name":"twitter:description","content":"介绍Mutelink无朗读声音、麦克风不识别或无法向VRChat发送文字时的检查步骤。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}]]},"headers":[],"relativePath":"zh/help/troubleshooting.md","filePath":"zh/help/troubleshooting.md"}'),i={name:"zh/help/troubleshooting.md"};function l(s,t,u,g,b,p){return h(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="困ったときの対処" tabindex="-1">故障排除 <a class="header-anchor" href="#困ったときの対処" aria-label="Permalink to &quot;故障排除 {#困ったときの対処}&quot;">​</a></h1><p>请从上往下依次检查。未列出的问题可通过设置 &gt; 其他 &gt; 关于 &gt; 发送问题与建议联系作者。</p><h2 id="読み上げの声が出ない" tabindex="-1">没有朗读声音 <a class="header-anchor" href="#読み上げの声が出ない" aria-label="Permalink to &quot;没有朗读声音 {#読み上げの声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>主界面合成语音按钮是否开启</td><td>关闭时不会朗读，点击开启</td></tr><tr><td>是否已选朗读声音</td><td>为输出语言选择VOICEVOX、Irodori-TTS或Qwen3-TTS；“无”仅发聊天框</td></tr><tr><td>声音是否下载完成</td><td>在设置 &gt; 其他 &gt; 模型与容量中确认，VOICEVOX还需选择角色</td></tr><tr><td>扬声器输出和音量</td><td>在设置 &gt; 发送 &gt; 朗读基础 &gt; 扬声器中检查设备及各设备音量</td></tr><tr><td>是否朗读译文</td><td>需要<a href="/Mutelink-releases/zh/about/supporter">支持版</a>，无许可证时译文只发聊天框</td></tr><tr><td>声音是否支持该语言</td><td>VOICEVOX/Irodori仅日语，Qwen支持10语言。无可用声音则仅发聊天框</td></tr><tr><td>提示显存已满、AI语音已关闭</td><td>因显存不足自动关闭朗读，文字仍发聊天框。不会自动恢复；空余后重新开启TTS即可恢复同一声音</td></tr></tbody></table><h2 id="vrchatの相手に声が届かない" tabindex="-1">VRChat中的对方听不到声音 <a class="header-anchor" href="#vrchatの相手に声が届かない" aria-label="Permalink to &quot;VRChat中的对方听不到声音 {#vrchatの相手に声が届かない}&quot;">​</a></h2><p>自己能听到朗读但对方听不到时，请检查以下项目。</p><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>是否安装虚拟声卡</td><td>检查Windows声音设置的CABLE Input/Output，没有则<a href="/Mutelink-releases/zh/guide/getting-started#_1-vb-audio-virtual-cableを入れる">安装</a></td></tr><tr><td>Mutelink是否输出到CABLE Input</td><td>在设置 &gt; 发送 &gt; 朗读基础 &gt; 扬声器中选择。未列出时刷新设备或重启Mutelink</td></tr><tr><td>VRChat麦克风是否为CABLE Output</td><td>查看VRChat设置 &gt; 音频</td></tr><tr><td><strong>重新选择VRChat麦克风</strong></td><td>即使已选CABLE Output，也先切换其他设备再切回来。VRChat保留启动时的设备，后安装或更改的线缆需重选；重启VRChat也可</td></tr><tr><td>VRChat是否静音</td><td>解除麦克风静音</td></tr><tr><td>Mutelink麦克风是否误选CABLE Output</td><td>应选择实际说话的麦克风</td></tr></tbody></table><p><img src="'+e+'" alt="VRChat麦克风设为CABLE Output"></p><h2 id="自分には読み上げが聞こえない" tabindex="-1">自己听不到朗读声音 <a class="header-anchor" href="#自分には読み上げが聞こえない" aria-label="Permalink to &quot;自己听不到朗读声音 {#自分には読み上げが聞こえない}&quot;">​</a></h2><p>仅选择CABLE Input时，对方能听到而自己听不到。请在设置 &gt; 发送 &gt; 朗读基础 &gt; 扬声器中同时选择CABLE Input和自己的扬声器/耳机，可分别调音量。</p><h2 id="vrchatに文字が出ない" tabindex="-1">VRChat不显示文字 <a class="header-anchor" href="#vrchatに文字が出ない" aria-label="Permalink to &quot;VRChat不显示文字 {#vrchatに文字が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>OSC是否开启</td><td>圆形菜单 &gt; Options &gt; OSC &gt; Enabled</td></tr><tr><td>主界面聊天框按钮</td><td>关闭时不发送，请开启</td></tr><tr><td>是否执行发送</td><td>自动发送关闭时，仅识别不会发送，请操作发送</td></tr><tr><td>是否设置随声音开始显示</td><td>设置 &gt; 发送 &gt; 朗读基础中的该选项会等声音开始再显示文字，最长8秒</td></tr><tr><td>VRChat是否隐藏聊天框</td><td>检查VRChat设置</td></tr></tbody></table><p><img src="'+a+'" alt="VRChat OSC已开启"></p><h2 id="音声認識が動かない・途切れる" tabindex="-1">语音识别不工作或中断 <a class="header-anchor" href="#音声認識が動かない・途切れる" aria-label="Permalink to &quot;语音识别不工作或中断 {#音声認識が動かない・途切れる}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>识别是否开启</td><td>开启主界面语音识别按钮</td></tr><tr><td>麦克风是否正确</td><td>设置 &gt; 说话 &gt; 麦克风中选择实际说话设备</td></tr><tr><td>Windows麦克风权限</td><td>设置 &gt; 隐私和安全性 &gt; 麦克风中允许桌面应用访问麦克风</td></tr><tr><td>模型是否下载</td><td>本地引擎首次需下载，查看设置 &gt; 其他 &gt; 模型与容量</td></tr><tr><td>无法连接识别服务</td><td>云端可能因网络或服务商问题中断。可在设置 &gt; 说话 &gt; 语言与识别中改用本地引擎（<a href="/Mutelink-releases/zh/compare/speech-recognition">对比</a>）</td></tr><tr><td>引擎是否支持语言</td><td>Parakeet日语TDT/Haas-ja仅日语，Parakeet英语不支持日语</td></tr><tr><td>仅特定词不出现</td><td>检查是否在排除词中</td></tr></tbody></table><p><img src="'+r+'" alt="Windows麦克风隐私设置"></p><h2 id="ダウンロードが失敗する" tabindex="-1">下载失败 <a class="header-anchor" href="#ダウンロードが失敗する" aria-label="Permalink to &quot;下载失败 {#ダウンロードが失敗する}&quot;">​</a></h2><p>失败时会显示原因。已下载部分会保留，再次点击下载即可续传。</p><table tabindex="0"><thead><tr><th>提示</th><th>处理方法</th></tr></thead><tbody><tr><td>连接中断或停止</td><td>检查网络后重试</td></tr><tr><td>下载源找不到文件</td><td>分发地址可能改变，请更新应用（设置 &gt; 其他 &gt; 关于）</td></tr><tr><td>下载服务器不响应</td><td>可能临时故障，稍后重试</td></tr><tr><td>文件损坏</td><td>已自动删除损坏文件，请重新下载</td></tr><tr><td>空间不足</td><td>清理后重试，容量可在设置 &gt; 其他 &gt; 模型与容量中查看</td></tr></tbody></table><p>可在设置 &gt; 其他 &gt; 模型与容量中删除未完成下载。</p><h2 id="irodori-tts・qwen3-ttsが動かない" tabindex="-1">Irodori-TTS或Qwen3-TTS不工作 <a class="header-anchor" href="#irodori-tts・qwen3-ttsが動かない" aria-label="Permalink to &quot;Irodori-TTS或Qwen3-TTS不工作 {#irodori-tts・qwen3-ttsが動かない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>是否支持Vulkan</td><td>需要支持Vulkan的GPU及驱动，请更新显卡驱动</td></tr><tr><td>显存是否足够</td><td>与VRChat和本地翻译共享；可降低VRChat画质、翻译改用CPU或使用VOICEVOX</td></tr><tr><td>仅首次朗读慢</td><td>首次需加载模型，启动或切换声音后请稍等</td></tr><tr><td>切换较慢</td><td>Irodori/Qwen同时仅加载一个，切换输出语言可能需要几秒</td></tr></tbody></table><h2 id="翻訳されない" tabindex="-1">没有翻译 <a class="header-anchor" href="#翻訳されない" aria-label="Permalink to &quot;没有翻译 {#翻訳されない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>输入输出是否不同</td><td>仅说话语言和输出语言不同时翻译</td></tr><tr><td>是否有可用引擎</td><td>设置 &gt; 翻译中填写Azure密钥或下载PLaMo/TranslateGemma（<a href="/Mutelink-releases/zh/compare/translation">对比</a>）</td></tr><tr><td>Azure密钥与区域</td><td>查看<a href="/Mutelink-releases/zh/guide/azure-translator#うまくいかないとき">Azure设置排错</a></td></tr><tr><td>有译文但无声音</td><td>译文朗读需<a href="/Mutelink-releases/zh/about/supporter">支持版</a>及支持该语言的声音（日语以外为Qwen）</td></tr></tbody></table><p>翻译失败时显示原因，并仅将原文发送到聊天框。</p><h2 id="聞こえた声が出ない" tabindex="-1">对方语音未显示 <a class="header-anchor" href="#聞こえた声が出ない" aria-label="Permalink to &quot;对方语音未显示 {#聞こえた声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>是否开启听取</td><td>用主界面👂按钮开始</td></tr><tr><td>VRChat是否运行</td><td>仅捕获设置 &gt; 听取 &gt; 对方语音指定的应用（默认VRChat），未启动时会等待</td></tr><tr><td>模型是否下载</td><td>查看设置 &gt; 其他 &gt; 模型与容量</td></tr><tr><td>BGM持续播放</td><td>可能无法判断语音结束，请在设置 &gt; 听取 &gt; 对方语音中提高检测严格度</td></tr><tr><td>不显示自己的朗读</td><td>不会捕获Mutelink自身的朗读</td></tr></tbody></table><h2 id="vrの中に画面が出ない" tabindex="-1">VR中不显示面板 <a class="header-anchor" href="#vrの中に画面が出ない" aria-label="Permalink to &quot;VR中不显示面板 {#vrの中に画面が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>处理方法</th></tr></thead><tbody><tr><td>SteamVR是否运行</td><td>Mutelink每几秒自动重连，必要时先开SteamVR再重启Mutelink</td></tr><tr><td>其他叠加层应用</td><td>检查与其他SteamVR叠加应用是否按钮冲突</td></tr><tr><td>想放到手背上</td><td>需<a href="/Mutelink-releases/zh/about/supporter">支持版自定义扩展</a>，否则固定在视野中</td></tr></tbody></table><h2 id="アプリが起動しない" tabindex="-1">应用无法启动 <a class="header-anchor" href="#アプリが起動しない" aria-label="Permalink to &quot;应用无法启动 {#アプリが起動しない}&quot;">​</a></h2><p>重新安装最新版并重启Windows。如仍无法启动，请通过BOOTH或作者X联系（<a href="https://x.com/nktssbat" target="_blank" rel="noreferrer">@nktssbat</a>、<a href="https://x.com/yuki54625" target="_blank" rel="noreferrer">@yuki54625</a>）。</p>',31)])])}const y=d(i,[["render",l]]);export{f as __pageData,y as default};
